// The letter grid: ten rows of eleven letters.
const ROWS = [
  'ITLISASTIME',
  'ACQUARTERDC',
  'TWENTYFIVEX',
  'HALFBTENFTO',
  'PASTERUNINE',
  'ONESIXTHREE',
  'FOURFIVETWO',
  'EIGHTELEVEN',
  'SEVENTWELVE',
  'TENSEOCLOCK',
]

// Each word's cells in the grid, as [row, column]. M* are the minute words, H* the hours.
const WORDS = {
  IT: [[0, 0], [0, 1]],
  IS: [[0, 3], [0, 4]],
  A: [[1, 0]],
  QUARTER: [[1, 2], [1, 3], [1, 4], [1, 5], [1, 6], [1, 7], [1, 8]],
  TWENTY: [[2, 0], [2, 1], [2, 2], [2, 3], [2, 4], [2, 5]],
  MFIVE: [[2, 6], [2, 7], [2, 8], [2, 9]],
  HALF: [[3, 0], [3, 1], [3, 2], [3, 3]],
  MTEN: [[3, 5], [3, 6], [3, 7]],
  TO: [[3, 9], [3, 10]],
  PAST: [[4, 0], [4, 1], [4, 2], [4, 3]],
  HNINE: [[4, 7], [4, 8], [4, 9], [4, 10]],
  HONE: [[5, 0], [5, 1], [5, 2]],
  HSIX: [[5, 3], [5, 4], [5, 5]],
  HTHREE: [[5, 6], [5, 7], [5, 8], [5, 9], [5, 10]],
  HFOUR: [[6, 0], [6, 1], [6, 2], [6, 3]],
  HFIVE: [[6, 4], [6, 5], [6, 6], [6, 7]],
  HTWO: [[6, 8], [6, 9], [6, 10]],
  HEIGHT: [[7, 0], [7, 1], [7, 2], [7, 3], [7, 4]],
  HELEVEN: [[7, 5], [7, 6], [7, 7], [7, 8], [7, 9], [7, 10]],
  HSEVEN: [[8, 0], [8, 1], [8, 2], [8, 3], [8, 4]],
  HTWELVE: [[8, 5], [8, 6], [8, 7], [8, 8], [8, 9], [8, 10]],
  HTEN: [[9, 0], [9, 1], [9, 2]],
  OCLOCK: [[9, 5], [9, 6], [9, 7], [9, 8], [9, 9], [9, 10]],
}

// The grid word and the spoken word for each hour, 1 to 12.
const HOUR_KEYS = {
  1: 'HONE', 2: 'HTWO', 3: 'HTHREE', 4: 'HFOUR', 5: 'HFIVE', 6: 'HSIX',
  7: 'HSEVEN', 8: 'HEIGHT', 9: 'HNINE', 10: 'HTEN', 11: 'HELEVEN', 12: 'HTWELVE',
}
const HOUR_LABELS = {
  1: 'ONE', 2: 'TWO', 3: 'THREE', 4: 'FOUR', 5: 'FIVE', 6: 'SIX',
  7: 'SEVEN', 8: 'EIGHT', 9: 'NINE', 10: 'TEN', 11: 'ELEVEN', 12: 'TWELVE',
}

// Each theme is [gradient start, gradient end, lit, dim, accent].
const THEMES = {
  midnight: ['#101826', '#28485c', '#fff4d6', '#51677a', '#d9a441'],
  aurora: ['#10251f', '#1f5c59', '#eafff6', '#6ea199', '#7dd3c7'],
  ember: ['#2a1512', '#6b2d22', '#fff0dd', '#93675f', '#e08d4f'],
  sage: ['#17231d', '#405846', '#f4f0d8', '#748371', '#c8b56b'],
  plum: ['#1f1630', '#54365e', '#fff0fb', '#7d6b86', '#d8a1c4'],
  ocean: ['#0b1d2b', '#17476b', '#edf8ff', '#5d7f95', '#76c7e8'],
  sandstone: ['#2f2118', '#806246', '#fff2dc', '#a58c74', '#e5b46b'],
  rosewood: ['#27171d', '#6a3342', '#fff1ee', '#9d6c75', '#df8f86'],
  mono: ['#111111', '#343434', '#ffffff', '#777777', '#cfcfcf'],
  white: ['#ffffff', '#f2f4f7', '#111827', '#9ca3af', '#334155'],
  paper: ['#f4ead7', '#d6c5a5', '#2f2a23', '#8f806c', '#8b5e34'],
  cobalt: ['#0d1838', '#2247a5', '#eef4ff', '#7589bd', '#f0c04f'],
  moss: ['#101b12', '#314b2f', '#f0f5df', '#72856b', '#a9c46c'],
}

const DIAL_LOCATIONS = ['top-right', 'top-left', 'bottom-right', 'bottom-left', 'hidden']

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

function isTrue(value) {
  return value === true || value === 'true' || value === 1 || value === '1'
}

function color(value, fallback) {
  const text = String(value || '').trim()
  return /^#[0-9a-fA-F]{6}$/.test(text) ? text : fallback
}

function pad2(value) {
  return value < 10 ? '0' + value : String(value)
}

function hour12(hour) {
  const value = ((hour % 12) + 12) % 12
  return value === 0 ? 12 : value
}

function themeFromConfig(config) {
  const selected = THEMES[config.theme]
  if (selected) {
    return { start: selected[0], end: selected[1], lit: selected[2], dim: selected[3], accent: selected[4] }
  }
  return {
    start: color(config.startColor, '#101826'),
    end: color(config.endColor, '#28485c'),
    lit: color(config.litColor, '#fff4d6'),
    dim: color(config.dimColor, '#51677a'),
    accent: color(config.accentColor, '#d9a441'),
  }
}

// The time rounded to five minutes: which grid words are lit, and the phrase they spell.
function makeClock(timeInfo) {
  // 9 only when the hour is missing or unreadable: midnight is hour 0, which
  // `|| 9` used to turn into nine (00:30 read "HALF PAST NINE").
  const rawHour = timeInfo ? Number(timeInfo.hour) : NaN
  const hour = Number.isFinite(rawHour) ? rawHour : 9
  const minute = Number(timeInfo && timeInfo.minute) || 0
  let rounded = Math.round(minute / 5) * 5
  let displayHour = hour
  if (rounded === 60) {
    rounded = 0
    displayHour += 1
  }
  const active = { IT: true, IS: true }
  const phrase = ['IT', 'IS']
  const add = (key) => {
    active[key] = true
  }
  const finish = (targetHour) => {
    const h = hour12(targetHour)
    add(HOUR_KEYS[h])
    phrase.push(HOUR_LABELS[h])
  }
  if (rounded === 0) {
    finish(displayHour)
    add('OCLOCK')
    phrase.push("O'CLOCK")
  } else if (rounded === 5) {
    add('MFIVE')
    add('PAST')
    phrase.push('FIVE', 'PAST')
    finish(displayHour)
  } else if (rounded === 10) {
    add('MTEN')
    add('PAST')
    phrase.push('TEN', 'PAST')
    finish(displayHour)
  } else if (rounded === 15) {
    add('A')
    add('QUARTER')
    add('PAST')
    phrase.push('A', 'QUARTER', 'PAST')
    finish(displayHour)
  } else if (rounded === 20) {
    add('TWENTY')
    add('PAST')
    phrase.push('TWENTY', 'PAST')
    finish(displayHour)
  } else if (rounded === 25) {
    add('TWENTY')
    add('MFIVE')
    add('PAST')
    phrase.push('TWENTY', 'FIVE', 'PAST')
    finish(displayHour)
  } else if (rounded === 30) {
    add('HALF')
    add('PAST')
    phrase.push('HALF', 'PAST')
    finish(displayHour)
  } else if (rounded === 35) {
    add('TWENTY')
    add('MFIVE')
    add('TO')
    phrase.push('TWENTY', 'FIVE', 'TO')
    finish(displayHour + 1)
  } else if (rounded === 40) {
    add('TWENTY')
    add('TO')
    phrase.push('TWENTY', 'TO')
    finish(displayHour + 1)
  } else if (rounded === 45) {
    add('A')
    add('QUARTER')
    add('TO')
    phrase.push('A', 'QUARTER', 'TO')
    finish(displayHour + 1)
  } else if (rounded === 50) {
    add('MTEN')
    add('TO')
    phrase.push('TEN', 'TO')
    finish(displayHour + 1)
  } else {
    add('MFIVE')
    add('TO')
    phrase.push('FIVE', 'TO')
    finish(displayHour + 1)
  }
  return {
    active,
    phrase,
    hour,
    minute,
    clock: timeInfo.clock || pad2(hour) + ':' + pad2(minute),
    date: timeInfo.date || '',
  }
}

function activeCells(active) {
  const cells = {}
  Object.keys(active).forEach((key) =>
    (WORDS[key] || []).forEach((coord) => {
      cells[coord[0] + ',' + coord[1]] = true
    })
  )
  return cells
}

function dialPosition(width, height, pad, radius, location) {
  if (location === 'hidden') return null
  const left = location === 'top-left' || location === 'bottom-left'
  const bottom = location === 'bottom-left' || location === 'bottom-right'
  return {
    x: left ? pad + radius : width - pad - radius,
    y: bottom ? height - pad - radius : pad + radius,
  }
}

// A flat fill, or the theme's gradient with a glow in the top right corner and a soft vignette.
function Background({ width, height, theme, useGradient }) {
  if (!useGradient) {
    return <rect x="0" y="0" width={width} height={height} fill={theme.start} />
  }
  const longSide = Math.max(width, height)
  return (
    <>
      <defs>
        <linearGradient id="bg" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2={width} y2={height}>
          <stop offset="0" stopColor={theme.start} />
          <stop offset="1" stopColor={theme.end} />
        </linearGradient>
        <radialGradient
          id="cornerGlow"
          gradientUnits="userSpaceOnUse"
          cx={(width * 0.78).toFixed(2)}
          cy={(height * 0.18).toFixed(2)}
          r={(longSide * 0.55).toFixed(2)}
        >
          <stop offset="0" stopColor={theme.accent} stopOpacity="0.16" />
          <stop offset="0.46" stopColor={theme.accent} stopOpacity="0.06" />
          <stop offset="1" stopColor={theme.accent} stopOpacity="0" />
        </radialGradient>
        <radialGradient
          id="vignette"
          gradientUnits="userSpaceOnUse"
          cx={(width / 2).toFixed(2)}
          cy={(height / 2).toFixed(2)}
          r={(longSide * 0.76).toFixed(2)}
        >
          <stop offset="0.52" stopColor="#000000" stopOpacity="0" />
          <stop offset="1" stopColor="#000000" stopOpacity="0.34" />
        </radialGradient>
      </defs>
      <rect x="0" y="0" width={width} height={height} fill="url(#bg)" />
      <rect x="0" y="0" width={width} height={height} fill="url(#cornerGlow)" />
      <rect x="0" y="0" width={width} height={height} fill="url(#vignette)" />
    </>
  )
}

// The small analog clock: a ring, twelve ticks, the hour and minute hands and a center dot.
function Dial({ x, y, radius, theme, hour, minute, scale }) {
  const stroke = clamp(radius * 0.055, 1 / scale, 4 / scale)
  const minuteAngle = (Math.PI * 2 * minute) / 60 - Math.PI / 2
  const hourAngle = (Math.PI * 2 * ((hour12(hour) % 12) + minute / 60)) / 12 - Math.PI / 2
  return (
    <>
      <circle
        cx={x.toFixed(2)}
        cy={y.toFixed(2)}
        r={(radius * 0.82).toFixed(2)}
        fill="none"
        stroke={theme.accent}
        strokeWidth={stroke.toFixed(2)}
        opacity="0.48"
      />
      {Array.from({ length: 12 }, (_, i) => {
        const angle = (Math.PI * 2 * i) / 12 - Math.PI / 2
        return (
          <line
            x1={(x + Math.cos(angle) * radius * 0.58).toFixed(2)}
            y1={(y + Math.sin(angle) * radius * 0.58).toFixed(2)}
            x2={(x + Math.cos(angle) * radius * 0.72).toFixed(2)}
            y2={(y + Math.sin(angle) * radius * 0.72).toFixed(2)}
            stroke={theme.lit}
            strokeWidth={stroke.toFixed(2)}
            opacity="0.35"
          />
        )
      })}
      <line
        x1={x.toFixed(2)}
        y1={y.toFixed(2)}
        x2={(x + Math.cos(hourAngle) * radius * 0.36).toFixed(2)}
        y2={(y + Math.sin(hourAngle) * radius * 0.36).toFixed(2)}
        stroke={theme.lit}
        strokeWidth={(stroke * 1.65).toFixed(2)}
        opacity="0.78"
      />
      <line
        x1={x.toFixed(2)}
        y1={y.toFixed(2)}
        x2={(x + Math.cos(minuteAngle) * radius * 0.52).toFixed(2)}
        y2={(y + Math.sin(minuteAngle) * radius * 0.52).toFixed(2)}
        stroke={theme.accent}
        strokeWidth={(stroke * 1.25).toFixed(2)}
        opacity="0.84"
      />
      <circle cx={x.toFixed(2)} cy={y.toFixed(2)} r={(radius * 0.07).toFixed(2)} fill={theme.accent} opacity="0.86" />
    </>
  )
}

// The classic word clock: every letter of the grid, the lit words bright with a soft dot behind each letter.
function GridClock({ width, height, clock, theme, showDigital, clockDialLocation, scale }) {
  const cols = 11
  const rows = 10
  const minSide = Math.min(width, height)
  const pad = minSide * (height > width ? 0.055 : 0.06)
  const footer = showDigital ? clamp(minSide * 0.10, 38 / scale, 76 / scale) : minSide * 0.03
  const cell = Math.min((width - pad * 2) / cols, (height - pad * 2 - footer) / rows)
  const gridWidth = cell * cols
  const gridHeight = cell * rows
  const left = (width - gridWidth) / 2
  const top = pad + Math.max(0, (height - pad * 2 - footer - gridHeight) / 2)
  const fontSize = cell * 0.62
  const cardPad = cell * 0.38
  const cells = activeCells(clock.active)
  const dialRadius = clamp(minSide * 0.047, 18 / scale, 54 / scale)
  const dial = dialPosition(width, height, pad, dialRadius, clockDialLocation)
  return (
    <>
      <rect
        x={(left - cardPad).toFixed(2)}
        y={(top - cardPad).toFixed(2)}
        width={(gridWidth + cardPad * 2).toFixed(2)}
        height={(gridHeight + cardPad * 2).toFixed(2)}
        rx={(cell * 0.34).toFixed(2)}
        ry={(cell * 0.34).toFixed(2)}
        fill="#ffffff"
        opacity="0.055"
      />
      <rect
        x={(left - cardPad).toFixed(2)}
        y={(top - cardPad).toFixed(2)}
        width={clamp(cell * 0.09, 3 / scale, 8 / scale).toFixed(2)}
        height={(gridHeight + cardPad * 2).toFixed(2)}
        rx={4 / scale}
        ry={4 / scale}
        fill={theme.accent}
        opacity="0.72"
      />
      {ROWS.map((letters, r) =>
        letters.split('').map((letter, c) => {
          const on = cells[r + ',' + c]
          const x = left + cell * (c + 0.5)
          const y = top + cell * (r + 0.56)
          return (
            <>
              {on && (
                <circle
                  cx={x.toFixed(2)}
                  cy={(y - cell * 0.03).toFixed(2)}
                  r={(cell * 0.37).toFixed(2)}
                  fill={theme.accent}
                  opacity="0.13"
                />
              )}
              <text
                x={x.toFixed(2)}
                y={y.toFixed(2)}
                textAnchor="middle"
                dominantBaseline="middle"
                fontFamily="PTSans-Bold.ttf"
                fontSize={fontSize.toFixed(2)}
                fontWeight="700"
                fill={on ? theme.lit : theme.dim}
                opacity={on ? '1' : '0.70'}
              >
                {letter}
              </text>
            </>
          )
        })
      )}
      {showDigital && (
        <text
          x={(width / 2).toFixed(2)}
          y={Math.min(height - pad * 0.65, top + gridHeight + footer * 0.72).toFixed(2)}
          textAnchor="middle"
          dominantBaseline="middle"
          fontFamily="PTSans-Regular.ttf"
          fontSize={clamp(minSide * 0.027, 12 / scale, 30 / scale).toFixed(2)}
          fill={theme.accent}
        >
          {clock.phrase.join(' ') + '  ·  ' + clock.clock}
        </text>
      )}
      {dial && (
        <Dial
          x={dial.x}
          y={dial.y}
          radius={dialRadius}
          theme={theme}
          hour={clock.hour}
          minute={clock.minute}
          scale={scale}
        />
      )}
    </>
  )
}

// The phrase set as two or three big centered lines under an accent rule, the last line in the accent color.
function TypesetClock({ width, height, clock, theme, showDigital, clockDialLocation, scale }) {
  const minSide = Math.min(width, height)
  const pad = minSide * (height > width ? 0.075 : 0.08)
  const usableWidth = width - pad * 2
  const phrase = clock.phrase.slice()
  const lines = ['IT IS']
  if (phrase.length <= 4) {
    lines.push(phrase.slice(2).join(' '))
  } else {
    lines.push(phrase.slice(2, phrase.length - 1).join(' '))
    lines.push(phrase[phrase.length - 1])
  }
  const cleanLines = lines.filter((line) => line.length > 0)
  let size = Math.min((height - pad * 2) / (cleanLines.length * 1.26), usableWidth / 7)
  cleanLines.forEach((line) => {
    size = Math.min(size, usableWidth / (line.length * 0.58))
  })
  size = clamp(size, minSide * 0.055, minSide * 0.18)
  const lineGap = size * 1.10
  const blockHeight = lineGap * (cleanLines.length - 1) + size
  const startY = (height - blockHeight) / 2 + size * 0.58
  const dialRadius = clamp(minSide * 0.052, 20 / scale, 60 / scale)
  const dialPad = clockDialLocation === 'bottom-left' || clockDialLocation === 'bottom-right' ? pad * 0.85 : pad * 1.12
  const dial = dialPosition(width, height, dialPad, dialRadius, clockDialLocation)
  return (
    <>
      <line
        x1={pad.toFixed(2)}
        y1={(pad * 1.12).toFixed(2)}
        x2={(width - pad).toFixed(2)}
        y2={(pad * 1.12).toFixed(2)}
        stroke={theme.accent}
        strokeWidth={clamp(minSide * 0.006, 2 / scale, 7 / scale).toFixed(2)}
        opacity="0.86"
      />
      {cleanLines.map((line, i) => (
        <text
          x={(width / 2).toFixed(2)}
          y={(startY + i * lineGap).toFixed(2)}
          textAnchor="middle"
          dominantBaseline="middle"
          fontFamily="PTSans-Bold.ttf"
          fontSize={size.toFixed(2)}
          fontWeight="700"
          fill={i === cleanLines.length - 1 ? theme.accent : theme.lit}
        >
          {line}
        </text>
      ))}
      {dial && (
        <Dial
          x={dial.x}
          y={dial.y}
          radius={dialRadius}
          theme={theme}
          hour={clock.hour}
          minute={clock.minute}
          scale={scale}
        />
      )}
      {showDigital && (
        <text
          x={(width / 2).toFixed(2)}
          y={(height - pad * 0.85).toFixed(2)}
          textAnchor="middle"
          dominantBaseline="middle"
          fontFamily="PTSans-Regular.ttf"
          fontSize={clamp(minSide * 0.03, 12 / scale, 34 / scale).toFixed(2)}
          fill={theme.dim}
        >
          {clock.clock + (clock.date ? ' · ' + clock.date : '')}
        </text>
      )}
    </>
  )
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const width = context.imageWidth || app.frame.width
  const height = context.imageHeight || app.frame.height
  const theme = themeFromConfig(app.config)
  const clock = makeClock(app.config.timeInfo || {})
  const showFlair = isTrue(app.config.showFlair)
  const showDigital = showFlair && isTrue(app.config.showDigital)
  const mode = app.config.displayMode === 'typeset' ? 'typeset' : 'grid'
  const clockDialLocation =
    showFlair && DIAL_LOCATIONS.indexOf(app.config.clockDialLocation) >= 0 ? app.config.clockDialLocation : 'hidden'
  const useGradient = isTrue(app.config.backgroundGradient)
  // The render scale: a .tsx app on a big panel (shorter edge about 1200 px) is told its canvas is half the
  // panel's size and its <svg> is stretched to fit. The few lengths fixed in panel pixels (the clamps' floors
  // and ceilings, the accent bar's corners) are divided by it so the panel shows the same layout at any scale.
  const scale = app.frame.scale || 1
  const Clock = mode === 'typeset' ? TypesetClock : GridClock
  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
      <Background width={width} height={height} theme={theme} useGradient={useGradient} />
      <Clock
        width={width}
        height={height}
        clock={clock}
        theme={theme}
        showDigital={showDigital}
        clockDialLocation={clockDialLocation}
        scale={scale}
      />
    </svg>
  )
}

